window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-060fcbfa2b269f19"]={"versions": [{"id": "FIG-060fcbfa2b269f19", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Farblegende bzw. Symbolschlüssel für Protokoll-Frame-Strukturen im Kontext des FlexRay-Netzwerkmanagements (<code>AUTOSAR_SWS_FlexrayNM</code>). Sie dient als Dekodierhilfe für Segmentierungsdarstellungen von FlexRay-Kommunikationszyklen bzw. -Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Farbkodierungs-Entitäten zur semantischen Unterscheidung der Bestandteile eines FlexRay-Rahmens:</p>\n<ul class=\"fig-list\"><li>Hellblau/Graublau hinterlegtes Kästchen mit Textzuordnung <code>Frame Header</code>\n</li><li>Hellgrün hinterlegtes Kästchen mit Textzuordnung <code>Frame Payload (Data)</code>\n</li><li>Hellorange/Beige hinterlegtes Kästchen mit Textzuordnung <code>Frame Trailer (CRC)</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Reine statische Legendenreferenz ohne dynamischen Sequenzablauf oder Zustandsübergänge. Ordnet visuellen Farbflächen die korrespondierenden Frame-Komponenten zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Farbkonvention für Schaubilder zur FlexRay-Frame-Struktur im Busschedule. Entwickler und Spezifikationsleser müssen die identifizierten Farben zur Unterscheidung von Protokoll-Overhead (Header, CRC-Trailer) und NM-/Nutzdaten (Payload) in zugehörigen Schedule-Diagrammen heranziehen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c291e3dadaa159ea", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Farblegende bzw. Symbolschlüssel für Protokoll-Frame-Strukturen im Kontext des FlexRay-Netzwerkmanagements (<code>AUTOSAR_SWS_FlexrayNM</code>). Sie dient als Dekodierhilfe für Segmentierungsdarstellungen von FlexRay-Kommunikationszyklen bzw. -Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Farbkodierungs-Entitäten zur semantischen Unterscheidung der Bestandteile eines FlexRay-Rahmens:</p>\n<ul class=\"fig-list\"><li>Hellblau/Graublau hinterlegtes Kästchen mit Textzuordnung <code>Frame Header</code>\n</li><li>Hellgrün hinterlegtes Kästchen mit Textzuordnung <code>Frame Payload (Data)</code>\n</li><li>Hellorange/Beige hinterlegtes Kästchen mit Textzuordnung <code>Frame Trailer (CRC)</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Reine statische Legendenreferenz ohne dynamischen Sequenzablauf oder Zustandsübergänge. Ordnet visuellen Farbflächen die korrespondierenden Frame-Komponenten zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Farbkonvention für Schaubilder zur FlexRay-Frame-Struktur im Busschedule. Entwickler und Spezifikationsleser müssen die identifizierten Farben zur Unterscheidung von Protokoll-Overhead (Header, CRC-Trailer) und NM-/Nutzdaten (Payload) in zugehörigen Schedule-Diagrammen heranziehen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c5498e53b8e798f9", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Farblegende bzw. Symbolschlüssel für Protokoll-Frame-Strukturen im Kontext des FlexRay-Netzwerkmanagements (<code>AUTOSAR_SWS_FlexrayNM</code>). Sie dient als Dekodierhilfe für Segmentierungsdarstellungen von FlexRay-Kommunikationszyklen bzw. -Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Farbkodierungs-Entitäten zur semantischen Unterscheidung der Bestandteile eines FlexRay-Rahmens:</p>\n<ul class=\"fig-list\"><li>Hellblau/Graublau hinterlegtes Kästchen mit Textzuordnung <code>Frame Header</code>\n</li><li>Hellgrün hinterlegtes Kästchen mit Textzuordnung <code>Frame Payload (Data)</code>\n</li><li>Hellorange/Beige hinterlegtes Kästchen mit Textzuordnung <code>Frame Trailer (CRC)</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Reine statische Legendenreferenz ohne dynamischen Sequenzablauf oder Zustandsübergänge. Ordnet visuellen Farbflächen die korrespondierenden Frame-Komponenten zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Farbkonvention für Schaubilder zur FlexRay-Frame-Struktur im Busschedule. Entwickler und Spezifikationsleser müssen die identifizierten Farben zur Unterscheidung von Protokoll-Overhead (Header, CRC-Trailer) und NM-/Nutzdaten (Payload) in zugehörigen Schedule-Diagrammen heranziehen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-060fcbfa2b269f19", "to": "FIG-c291e3dadaa159ea", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c291e3dadaa159ea", "to": "FIG-c5498e53b8e798f9", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
